/* Original vector CBD scene: no remote assets or external requests. */
(function (root) {
  "use strict";
  const icons = {
    city: "M3 20V9l6-4v15m0-12 6-5v17m0-10 6-3v13M2 21h20", cards: "m5 5 11-2 4 15-11 2zM4 9l-2 1 4 12 10-3", bag: "M5 7h14l2 14H3L5 7Zm3 0V5a4 4 0 0 1 8 0v2", book: "M3 4h7l2 2 2-2h7v16h-7l-2 2-2-2H3zM12 6v16", clock: "M12 8v5l3 2M21 12a9 9 0 1 1-18 0 9 9 0 0 1 18 0", gear: "M9 3h6l1 4 4 2v6l-4 2-1 4H9l-1-4-4-2V9l4-2zM15 12a3 3 0 1 1-6 0 3 3 0 0 1 6 0", coin: "M20 12a8 8 0 1 1-16 0 8 8 0 0 1 16 0M14 7h-4v10h4M8 10h8m-8 4h8", arrow: "m9 5 7 7-7 7", wood: "m4 16 10-10 6 6-10 10zM4 16l6 6m-3-9 6 6", blueprint: "M4 3h16v18H4zM7 8h10M7 12h6M7 16h10",
  };
  function icon(name) { return `<svg class="ico" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.7" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><path d="${icons[name] || icons.city}"/></svg>`; }
  function tower(x, y, width, height, color, tier, kind = "skyline") {
    const rows = Math.max(2, Math.floor(height / 18)), top = -height,
      lights = Array.from({ length: rows }, (_, i) => {
        const yy = top + 18 + i * 17, active = (i + Math.round(height)) % 4 !== 2;
        return `<path d="M8 ${yy} ${width - 7} ${yy + width * .28}" stroke="${active ? (i % 2 ? "#65dff1" : "#ffe19a") : "#27384f"}" stroke-width="4.5" opacity="${active ? ".9" : ".42"}"/>`;
      }).join(""),
      base = `<ellipse cx="6" cy="17" rx="${width * 1.08}" ry="21" fill="#000" opacity=".55"/><path d="M-${width * .38} 8 ${width * .52} 34 ${width * 1.28} 8 ${width * .35} -18Z" fill="#101827" stroke="#c8a458" stroke-width="1.4"/><path d="M-${width * .38} 8v14l${width * .9} 26V34Z" fill="#070d17"/><path d="M${width * .52} 34v14l${width * .76} -26V8Z" fill="#172338"/>`,
      block = (left, w, h, fill = color) => `<path d="M${left} 0 ${left + w} ${w * .28} ${left + w} ${w * .28 - h} ${left} ${-h}Z" fill="${fill}" stroke="#d4b665" stroke-width="1.2"/><path d="M${left} 0 ${left - w * .34} ${-w * .18} ${left - w * .34} ${-h - w * .18} ${left} ${-h}Z" fill="#08101d"/><path d="M${left} ${-h} ${left + w} ${w * .28 - h} ${left + w * .52} ${w * .06 - h} ${left - w * .34} ${-h - w * .18}Z" fill="#b58b3e"/>`,
      crown = height > 125 ? `<path class="tower-beacon" d="M${width * .45} ${top - 8}v-${Math.min(42, height * .24)}" stroke="#f7d477" stroke-width="3"/><circle class="tower-beacon" cx="${width * .45}" cy="${top - 12 - Math.min(42, height * .24)}" r="4" fill="#fff4b0"/>` : "";
    let body;
    if (kind === "trend") body = `${block(0, width, height)}<path d="M${width * .16} ${top + 6} ${width * .52} ${top - 22} ${width * .82} ${top + width * .22}" fill="#d9ba69"/><path d="M${width * .52} ${top - 22}v-${Math.min(48, height * .27)}" stroke="#6ce5f5" stroke-width="4"/>${lights}`;
    else if (kind === "value") body = `${block(-width * .18, width * .62, height * .82, "#4e3248")}${block(width * .34, width * .62, height, color)}<path d="M-${width * .18} ${top * .52}h${width * 1.14}" stroke="#f0ce78" stroke-width="5"/>${lights}`;
    else if (kind === "defense") body = `${block(-width * .16, width * 1.22, height * .48, "#183c39")}${block(0, width, height * .76, color)}${block(width * .18, width * .62, height, "#2d6259")}<path d="M-${width * .1} ${top * .5}h${width * 1.2}" stroke="#78e1c4" stroke-width="4" opacity=".75"/>${lights}`;
    else if (kind === "research") body = `${block(0, width, height, color)}<path d="M${width * .12} ${top + 10}Q${width * .5} ${top - 20} ${width * .9} ${top + width * .22}" fill="#8a7ac7" stroke="#e4c974"/><path d="M${width * .15} ${top + 23}v${height - 35}M${width * .52} ${top + 28}v${height - 31}" stroke="#83e5f4" stroke-width="3" opacity=".65"/>${lights}`;
    else body = `${block(0, width, height, color)}${lights}`;
    return `<g class="corporate-building building-${kind} tier-${tier}" transform="translate(${x} ${y})">${base}${body}${crown}<g class="tower-sign"><rect x="${width * .04}" y="-${Math.min(44, height * .34)}" width="${width * .82}" height="14" rx="3" fill="#050a12" stroke="#d0ad5d"/><path d="M${width * .16} -${Math.min(34, height * .34 - 10)}h${width * .55}" stroke="#f2d581" stroke-width="3"/></g></g>`;
  }
  function lot(plot, district, locked, interactive) {
    const investment = district?.budget || 0, floors = district?.floors || 0, height = district ? Math.min(205, 52 + floors * 25 + Math.sqrt(Math.max(0, investment)) * 0.75 + (district.development || 0) * 0.35) : 0, tier = !district ? "待开发" : height < 90 ? "小平层" : height < 135 ? "集团总部" : height < 180 ? "金融中心" : "摩天大楼", action = interactive ? `role="button" tabindex="0" data-do="district" data-id="${plot.id}" aria-label="${plot.label} ${district ? "进入总部" : "建设总部"}"` : "";
    return `<g class="plot ${district ? "constructed" : "vacant"} ${locked ? "locked" : ""}" ${action} transform="translate(${plot.x} ${plot.y})"><path class="plotglow" d="M-82 4 0-38 88 6 5 49Z" fill="${district ? "#17263a" : "#111b2b"}" stroke="${locked ? "#485268" : "#c7a455"}" stroke-width="3" stroke-dasharray="${district ? "0" : "9 7"}"/>${district ? tower(-8, 10, 76, height, plot.color, tier, plot.id) : `<path d="M-18 0h38M1-19v38" stroke="${locked ? "#596276" : "#d5b35e"}" stroke-width="7" stroke-linecap="round"/>`}<g transform="translate(3 72)" filter="url(#shadow)"><rect x="-72" y="-18" width="144" height="38" rx="6" fill="${locked ? "#222a38" : "#0b1220"}" stroke="${locked ? "#4b5566" : "#b8944b"}"/><text text-anchor="middle" y="5" fill="${locked ? "#7e8798" : "#f1d17d"}" font-size="16" font-weight="800">${locked ? "待收购 · " : ""}${plot.label}</text></g>${district ? `<text x="3" y="105" text-anchor="middle" fill="#c8d2e4" font-size="12">${tier} · ${floors} 层策略</text>` : `<text x="3" y="103" text-anchor="middle" fill="#8f9aac" font-size="11">${locked ? "等待总部地契" : "点击成立总部"}</text>`}</g>`;
  }
  function map(s, { interactive = true } = {}) {
    const city = s?.city || { districts: [], blueprints: ["trend"] }, plots = [{ id: "trend", x: 385, y: 390, label: "趋势资本", color: "#1f5f87" }, { id: "value", x: 660, y: 410, label: "价值控股", color: "#6a405d" }, { id: "defense", x: 340, y: 700, label: "风控中心", color: "#245d52" }, { id: "research", x: 665, y: 700, label: "量化研究院", color: "#514382" }], skyline = [[70, 220, 42, 88], [145, 205, 34, 125], [520, 210, 40, 105], [755, 250, 38, 138], [820, 330, 30, 92]].map(([x, y, w, h], i) => tower(x, y, w, h, i % 2 ? "#17263c" : "#1b3047", "远景", "skyline")).join("");
    return `<svg class="world cbd-world" viewBox="0 0 900 950" role="img" aria-label="都市集团版图，可点击四个总部"><defs><linearGradient id="sky" x1="0" y1="0" x2="0" y2="1"><stop stop-color="#060914"/><stop offset=".52" stop-color="#15233b"/><stop offset="1" stop-color="#090d16"/></linearGradient><radialGradient id="halo"><stop stop-color="#6c83b0" stop-opacity=".45"/><stop offset="1" stop-color="#111827" stop-opacity="0"/></radialGradient><pattern id="grid" width="44" height="44" patternUnits="userSpaceOnUse"><path d="M44 0H0V44" fill="none" stroke="#718096" stroke-opacity=".08"/></pattern><filter id="shadow"><feDropShadow dx="0" dy="8" stdDeviation="6" flood-color="#000" flood-opacity=".65"/></filter></defs><rect width="900" height="950" fill="url(#sky)"/><circle cx="650" cy="160" r="320" fill="url(#halo)"/><rect width="900" height="950" fill="url(#grid)"/>${skyline}<path d="M-40 530 900 70M80 960 940 520M-40 720 540 950M360 0 940 300" stroke="#080c14" stroke-width="92"/><path d="M-40 530 900 70M80 960 940 520M-40 720 540 950M360 0 940 300" stroke="#273348" stroke-width="68"/><path d="M-40 530 900 70M80 960 940 520M-40 720 540 950M360 0 940 300" stroke="#d6b764" stroke-opacity=".55" stroke-width="2" stroke-dasharray="18 28"/><g class="traffic" fill="#ffd875">${[[160, 430], [390, 320], [590, 215], [185, 815], [480, 760], [745, 620]].map(([x, y]) => `<rect x="${x}" y="${y}" width="18" height="5" rx="2"/>`).join("")}</g>${plots.map((p) => lot(p, city.districts.find((d) => d.id === p.id), !city.blueprints.includes(p.id), interactive)).join("")}</svg>`;
  }
  root.CityArt = { map, icon };
})(window);
